class NinjaError(Exception):
    pass

class ParseError(NinjaError):
    def __init__(self, filename, lineno, message, line=None, col=None):
        self.filename = filename
        self.lineno = lineno
        self.message = message
        self.line = line
        self.col = col
        super().__init__(self.format())
    def format(self):
        if self.line is not None and self.col is not None:
            return f"ninja: error: {self.filename}:{self.lineno}: {self.message}\n{self.line}\n{' ' * max(0,self.col)}^ near here"
        return f"ninja: error: {self.filename}:{self.lineno}: {self.message}"

class FatalError(NinjaError):
    pass

class BuildError(NinjaError):
    pass

class Scope:
    def __init__(self, parent=None, is_root=False):
        self.parent = parent
        self.vars = OrderedDict()
        self.rules = OrderedDict()
        self.is_root = is_root
    def lookup_var(self, name):
        if name in self.vars:
            return self.vars[name]
        if self.parent:
            return self.parent.lookup_var(name)
        return ""
    def lookup_rule(self, name):
        if name in self.rules:
            return self.rules[name]
        if self.parent:
            return self.parent.lookup_rule(name)
        return None

class Rule:
    def __init__(self, name, bindings, line=0):
        self.name = name
        self.bindings = OrderedDict(bindings)  # raw, late-expanded strings
        self.line = line

class Node:
    def __init__(self, path, ordinal):
        self.path = path
        self.ordinal = ordinal
        self.in_edge = None
        self.out_edges = []

class Edge:
    def __init__(self, index, rule, scope, filename, line):
        self.index = index
        self.rule = rule
        self.scope = scope
        self.filename = filename
        self.line = line
        self.explicit_outputs = []
        self.implicit_outputs = []
        self.explicit_inputs = []
        self.implicit_inputs = []
        self.order_only_inputs = []
        self.validations = []
        self.bindings = OrderedDict()  # already expanded build bindings
    @property
    def outputs(self):
        return self.explicit_outputs + self.implicit_outputs
    @property
    def inputs(self):
        return self.explicit_inputs + self.implicit_inputs + self.order_only_inputs
    @property
    def normal_inputs(self):
        return self.explicit_inputs + self.implicit_inputs
    @property
    def rule_name(self):
        return self.rule.name if self.rule else "phony"
    def is_phony(self):
        return self.rule_name == "phony"

class Pool:
    def __init__(self, name, depth):
        self.name = name
        self.depth = depth

class State:
    def __init__(self, opts=None):
        self.opts = opts
        self.root_scope = Scope(is_root=True)
        self.nodes = OrderedDict()
        self.edges = []
        self.defaults = []
        self.pools = {"console": Pool("console", 1)}
        self.required_version = None
        self.warnings = []
        self.node_counter = 0
    def canonical(self, path):
        if path == "":
            return path
        p = path.replace('\\', '/')
        # Ninja canonicalizes simple ./ and a//b forms on POSIX.
        p = os.path.normpath(p)
        if p == ".":
            p = ""
        if path.startswith("//") and not p.startswith("//"):
            p = "/" + p
        return p
    def get_node(self, path):
        path = self.canonical(path)
        n = self.nodes.get(path)
        if n is None:
            n = Node(path, self.node_counter)
            self.node_counter += 1
            self.nodes[path] = n
        return n

# ---------- lexical expansion ----------

_varname_re = re.compile(r'[A-Za-z0-9_.-]+')

def version_tuple(s):
    nums = []
    for part in re.split(r'[^0-9]+', s):
        if part != '':
            nums.append(int(part))
    while len(nums) < 3:
        nums.append(0)
    return tuple(nums[:3])

def check_required_version(state, value):
    state.required_version = value
    if version_tuple(value) > version_tuple(VERSION):
        raise FatalError(f"ninja: fatal: ninja version ({VERSION}) incompatible with build file ninja_required_version version ({value}).")

def expand_string(raw, lookup, state=None, filename=None, lineno=0, line=None, colbase=0):
    """Expand Ninja $ escapes and variable references in a single string."""
    out = []
    i = 0
    L = len(raw)
    while i < L:
        c = raw[i]
        if c != '$':
            out.append(c); i += 1; continue
        if i + 1 >= L:
            # In real Ninja a trailing $ at EOF may be reported on following line;
            # this close diagnostic is adequate for normal manifests.
            raise ParseError(filename or "build.ninja", lineno + 1, "unexpected EOF")
        n = raw[i+1]
        if n == '$':
            out.append('$'); i += 2
        elif n == ' ':
            out.append(' '); i += 2
        elif n == ':':
            out.append(':'); i += 2
        elif n == '^':
            if state is None or state.required_version is None or version_tuple(state.required_version) < (1,14,0):
                raise ParseError(filename or "build.ninja", lineno,
                                 "using $^ escape requires specifying 'ninja_required_version' with version greater or equal 1.14",
                                 line, colbase)
            out.append('\n'); i += 2
        elif n == '{':
            j = raw.find('}', i+2)
            if j < 0:
                raise ParseError(filename or "build.ninja", lineno, "bad $-escape (literal $ must be written as $$)", line, colbase+i)
            name = raw[i+2:j]
            out.append(lookup(name))
            i = j + 1
        elif n == '\n':
            # Logical lines are already joined, but keep the behavior if present.
            i += 2
            while i < L and raw[i] in ' \t':
                i += 1
        else:
            m = _varname_re.match(raw, i+1)
            if m:
                out.append(lookup(m.group(0)))
                i = m.end()
            else:
                raise ParseError(filename or "build.ninja", lineno, "bad $-escape (literal $ must be written as $$)", line, colbase+i)
    return ''.join(out)

def split_path_tokens(raw):
    """Split a build/default path list into raw tokens; $-escaped spaces stay in token."""
    toks = []
    cur = []
    i = 0
    L = len(raw)
    while i < L:
        c = raw[i]
        if c in ' \t':
            if cur:
                toks.append(''.join(cur)); cur=[]
            i += 1
            while i < L and raw[i] in ' \t':
                i += 1
            continue
        if c == '$' and i+1 < L and raw[i+1] == ' ':
            cur.append('$ '); i += 2; continue
        cur.append(c); i += 1
    if cur:
        toks.append(''.join(cur))
    return toks

def find_unescaped_colon(s):
    i = 0
    while i < len(s):
        if s[i] == '$':
            i += 2
            continue
        if s[i] == ':':
            return i
        i += 1
    return -1

def parse_assignment_text(text):
    eq = text.find('=')
    if eq < 0:
        return None, None
    name = text[:eq].strip()
    # Leading whitespace after '=' is stripped; trailing whitespace is significant.
    val = text[eq+1:]
    val = val.lstrip(' \t')
    return name, val

# ---------- parser ----------

class Parser:
    def __init__(self, state):
        self.state = state

    def logical_lines(self, filename):
        try:
            with open(filename, 'r', encoding='utf-8', errors='surrogateescape') as f:
                physical = f.readlines()
        except FileNotFoundError:
            raise FatalError(f"ninja: error: loading '{filename}': No such file or directory")
        lines = []
        i = 0
        while i < len(physical):
            start = i + 1
            text = physical[i].rstrip('\n')
            if text.endswith('\r'):
                text = text[:-1]
            while text.endswith('$'):
                # $ followed by newline: continue logical line. If this is the last
                # physical line, Ninja reports unexpected EOF.
                if i + 1 >= len(physical):
                    raise ParseError(filename, start + 1, "unexpected EOF")
                text = text[:-1]
                i += 1
                nxt = physical[i].rstrip('\n')
                if nxt.endswith('\r'):
                    nxt = nxt[:-1]
                nxt = nxt.lstrip(' \t')
                text += nxt
            lines.append((start, text))
            i += 1
        return lines

    def parse_file(self, filename, scope):
        lines = self.logical_lines(filename)
        i = 0
        while i < len(lines):
            lineno, line = lines[i]
            stripped = line.strip()
            if stripped == '' or stripped.startswith('#'):
                i += 1; continue
            if line[0] in ' \t':
                raise ParseError(filename, lineno, "unexpected indent")
            if line.startswith('rule') and (len(line)==4 or line[4] in ' \t'):
                i = self.parse_rule(filename, lines, i, scope); continue
            if line.startswith('build') and (len(line)==5 or line[5] in ' \t'):
                i = self.parse_build(filename, lines, i, scope); continue
            if line.startswith('default') and (len(line)==7 or line[7] in ' \t'):
                rest = line[7:].strip(' \t')
                toks = split_path_tokens(rest)
                for t in toks:
                    p = expand_string(t, scope.lookup_var, self.state, filename, lineno, line, line.find(t) if t else 0)
                    p = self.state.canonical(p)
                    if p not in self.state.nodes or self.state.nodes[p].in_edge is None:
                        col = line.rfind(t) + len(t) if t else len(line)
                        raise ParseError(filename, lineno, f"unknown target '{p}'", line, col)
                    self.state.defaults.append(self.state.get_node(p))
                i += 1; continue
            if line.startswith('include') and (len(line)==7 or line[7] in ' \t'):
                raw = line[7:].strip(' \t')
                path = expand_string(raw, scope.lookup_var, self.state, filename, lineno, line, line.find(raw) if raw else 0)
                self.parse_file(path, scope)
                i += 1; continue
            if line.startswith('subninja') and (len(line)==8 or line[8] in ' \t'):
                raw = line[8:].strip(' \t')
                path = expand_string(raw, scope.lookup_var, self.state, filename, lineno, line, line.find(raw) if raw else 0)
                child = Scope(parent=scope)
                self.parse_file(path, child)
                i += 1; continue
            if line.startswith('pool') and (len(line)==4 or line[4] in ' \t'):
                i = self.parse_pool(filename, lines, i, scope); continue
            # top-level variable assignment
            name, val = parse_assignment_text(line)
            if name is not None:
                expanded = expand_string(val, scope.lookup_var, self.state, filename, lineno, line, line.find(val) if val else len(line))
                scope.vars[name] = expanded
                if name == 'ninja_required_version':
                    check_required_version(self.state, expanded)
                i += 1; continue
            # Approximate lexer diagnostic for unknown top-level identifier.
            parts = line.split(None, 1)
            got = "identifier" if parts else "newline"
            col = len(parts[0]) if parts else 0
            raise ParseError(filename, lineno, f"expected '=', got {got}", line, col)

    def parse_rule(self, filename, lines, i, scope):
        lineno, line = lines[i]
        name = line[4:].strip(' \t')
        if not name:
            raise ParseError(filename, lineno, "expected rule name", line, len(line))
        if name in scope.rules:
            raise ParseError(filename, lineno, f"duplicate rule '{name}'", line, line.find(name))
        bindings = OrderedDict()
        i += 1
        while i < len(lines):
            lno, l = lines[i]
            st = l.strip()
            if st == '' or st.startswith('#'):
                i += 1; continue
            if not (l[0] in ' \t'):
                break
            inner = l.lstrip(' \t')
            key, val = parse_assignment_text(inner)
            if key is None:
                raise ParseError(filename, lno, "expected variable assignment", l, len(l))
            if key not in RULE_VARS:
                raise ParseError(filename, lno, f"unexpected variable '{key}'", l, l.find(val) + len(val) if val else len(l))
            bindings[key] = val
            i += 1
        # Validation mirrors Ninja's eager checks.
        if 'command' not in bindings:
            raise ParseError(filename, (lines[i][0] if i < len(lines) else lineno+len(bindings)+1), "expected 'command =' line")
        if ('rspfile' in bindings) ^ ('rspfile_content' in bindings):
            raise ParseError(filename, (lines[i][0] if i < len(lines) else lineno+len(bindings)+1), "rspfile and rspfile_content need to be both specified")
        scope.rules[name] = Rule(name, bindings, lineno)
        return i

    def parse_pool(self, filename, lines, i, scope):
        lineno, line = lines[i]
        name = line[4:].strip(' \t')
        if not name:
            raise ParseError(filename, lineno, "expected pool name", line, len(line))
        depth = None
        i += 1
        while i < len(lines):
            lno, l = lines[i]
            st = l.strip()
            if st == '' or st.startswith('#'):
                i += 1; continue
            if not (l[0] in ' \t'):
                break
            inner = l.lstrip(' \t')
            key, val = parse_assignment_text(inner)
            if key != 'depth':
                got = key if key else ''
                raise ParseError(filename, lno, f"unexpected variable '{got}'", l, l.find(val) + len(val) if val else len(l))
            ev = expand_string(val, scope.lookup_var, self.state, filename, lno, l, l.find(val) if val else len(l))
            try: depth = int(ev)
            except Exception: depth = 0
            i += 1
        if depth is None:
            raise ParseError(filename, (lines[i][0] if i < len(lines) else lineno+1), "expected 'depth =' line")
        self.state.pools[name] = Pool(name, depth)
        return i

    def parse_build(self, filename, lines, i, scope):
        lineno, line = lines[i]
        rest = line[5:].lstrip(' \t')
        colon = find_unescaped_colon(rest)
        if colon < 0:
            raise ParseError(filename, lineno, "expected ':', got newline ($ also escapes ':')", line, len(line))
        outs_raw = rest[:colon]
        rhs = rest[colon+1:].strip(' \t')
        out_tokens = split_path_tokens(outs_raw)
        explicit_out_raw, implicit_out_raw = [], []
        cur = explicit_out_raw
        for t in out_tokens:
            if t == '|':
                cur = implicit_out_raw; continue
            cur.append(t)
        def exp_path(t):
            return self.state.canonical(expand_string(t, scope.lookup_var, self.state, filename, lineno, line, line.find(t) if t else 0))
        explicit_outs = [exp_path(t) for t in explicit_out_raw]
        implicit_outs = [exp_path(t) for t in implicit_out_raw]
        if not explicit_outs and not implicit_outs:
            raise ParseError(filename, lineno, "expected path", line, line.find('build')+5)
        rhs_tokens = split_path_tokens(rhs)
        if not rhs_tokens:
            raise ParseError(filename, lineno, "expected build command name", line, len(line))
        rule_name = rhs_tokens[0]
        rule = None
        if rule_name == 'phony':
            rule = Rule('phony', OrderedDict(), lineno)
        else:
            rule = scope.lookup_rule(rule_name)
            if rule is None:
                raise ParseError(filename, lineno, f"unknown build rule '{rule_name}'", line, line.find(rule_name))
        edge = Edge(len(self.state.edges), rule, scope, filename, lineno)
        seg = 'explicit'
        for t in rhs_tokens[1:]:
            if t == '|':
                seg = 'implicit'; continue
            if t == '||':
                seg = 'order'; continue
            if t == '|@':
                seg = 'validation'; continue
            p = exp_path(t)
            n = self.state.get_node(p)
            if seg == 'explicit': edge.explicit_inputs.append(n)
            elif seg == 'implicit': edge.implicit_inputs.append(n)
            elif seg == 'order': edge.order_only_inputs.append(n)
            else: edge.validations.append(n)
        for p in explicit_outs:
            edge.explicit_outputs.append(self.state.get_node(p))
        for p in implicit_outs:
            edge.implicit_outputs.append(self.state.get_node(p))
        # Phony self-reference warning/removal.
        if edge.is_phony():
            outs = {n.path for n in edge.outputs}
            new_inputs = []
            for n in edge.explicit_inputs:
                if n.path in outs:
                    mode = self.state.opts.phonycycle if self.state.opts else 'warn'
                    if mode == 'err':
                        raise FatalError(f"ninja: error: dependency cycle: {n.path} -> {n.path} [-w phonycycle=err]")
                    self.state.warnings.append(f"ninja: warning: phony target '{n.path}' names itself as an input; ignoring [-w phonycycle=warn]")
                else:
                    new_inputs.append(n)
            edge.explicit_inputs = new_inputs
        # Duplicate outputs are fatal.
        for n in edge.outputs:
            if n.in_edge is not None:
                raise ParseError(filename, lineno + 1, f"multiple rules generate {n.path}")
        # Build-level bindings.
        i += 1
        while i < len(lines):
            lno, l = lines[i]
            st = l.strip()
            if st == '' or st.startswith('#'):
                i += 1; continue
            if not (l[0] in ' \t'):
                break
            inner = l.lstrip(' \t')
            key, val = parse_assignment_text(inner)
            if key is None:
                raise ParseError(filename, lno, "expected variable assignment", l, len(l))
            ev = expand_string(val, scope.lookup_var, self.state, filename, lno, l, l.find(val) if val else len(l))
            edge.bindings[key] = ev
            i += 1
        self.state.edges.append(edge)
        for n in edge.outputs:
            n.in_edge = edge
        for n in edge.explicit_inputs + edge.implicit_inputs + edge.order_only_inputs + edge.validations:
            n.out_edges.append(edge)
        # Validate pool references at edge creation time.
        pool = eval_edge_var(edge, 'pool', self.state)
        if pool and pool not in self.state.pools:
            raise ParseError(filename, i+1 if isinstance(i, int) else lineno, f"unknown pool name '{pool}'")
        return i

# ---------- evaluation ----------

def eval_edge_var(edge, name, state, stack=None):
    if stack is None: stack = set()
    # Built-ins.
    if name == 'in':
        return ' '.join(n.path for n in edge.explicit_inputs)
    if name == 'in_newline':
        return '\n'.join(n.path for n in edge.explicit_inputs)
    if name == 'out':
        return ' '.join(n.path for n in edge.explicit_outputs)
    if name in edge.bindings:
        return edge.bindings[name]
    if edge.rule and name in edge.rule.bindings:
        if name in stack:
            return ''
        raw = edge.rule.bindings[name]
        stack.add(name)
        def lookup(x):
            return eval_edge_var(edge, x, state, stack)
        try:
            return expand_string(raw, lookup, state, edge.filename, edge.line, None, 0)
        finally:
            stack.discard(name)
    return edge.scope.lookup_var(name)

def edge_command(edge, state):
    return eval_edge_var(edge, 'command', state)

def edge_description(edge, state):
    return eval_edge_var(edge, 'description', state)

def truthy(s):
    return str(s).strip() not in ('', '0')

def command_hash(cmd):
    return hashlib.sha1(cmd.encode('utf-8', 'surrogateescape')).hexdigest()[:16]

def default_jobs():
    # Ninja uses CPU quota where available, then adds two jobs.
    try:
        data = open('/sys/fs/cgroup/cpu.max').read().strip().split()
        if len(data) >= 2 and data[0] != 'max':
            q = int(data[0]); p = int(data[1])
            if q > 0 and p > 0:
                cores = max(1, int((q + p - 1)//p))
                return cores + 2
    except Exception:
        pass
    try:
        return (os.cpu_count() or 1) + 2
    except Exception:
        return 2

def usage_text():
    j = default_jobs()
    return f"""usage: ninja [options] [targets...]

if targets are unspecified, builds the 'default' target (see manual).

options:
  --version      print ninja version (\"{VERSION}\")
  -v, --verbose  show all command lines while building
  --quiet        don't show progress status, just command output

  -C DIR   change to DIR before doing anything else
  -f FILE  specify input build file [default=build.ninja]

  -j N     run N jobs in parallel (0 means infinity) [default={j} on this system]
  -k N     keep going until N jobs fail (0 means infinity) [default=1]
  -l N     do not start new jobs if the load average is greater than N
  -n       dry run (don't run commands but act like they succeeded)

  -d MODE  enable debugging (use '-d list' to list modes)
  -t TOOL  run a subtool (use '-t list' to list subtools)
    terminates toplevel options; further flags are passed to the tool
  -w FLAG  adjust warnings (use '-w list' to list warnings)"""

DEBUG_LIST = """debugging modes:
  stats        print operation counts/timing info
  explain      explain what caused a command to execute
  keepdepfile  don't delete depfiles after they're read by ninja
  keeprsp      don't delete @response files on success
multiple modes can be enabled via -d FOO -d BAR"""
WARN_LIST = """warning flags:
  phonycycle={err,warn}  phony build statement references itself"""

class Options:
    def __init__(self):
        self.verbose = False
        self.quiet = False
        self.dry_run = False
        self.chdir = None
        self.buildfile = 'build.ninja'
        self.jobs = default_jobs()
        self.keep_going = 1
        self.load = None
        self.debug = set()
        self.tool = None
        self.tool_args = []
        self.targets = []
        self.phonycycle = 'warn'

# ---------- metadata ----------

class BuildLog:
    def __init__(self, path):
        self.path = path
        self.entries = {}  # output -> dict(mtime, hash)
    def load(self):
        self.entries = {}
        try:
            with open(self.path, 'r', encoding='utf-8', errors='replace') as f:
                for line in f:
                    line = line.rstrip('\n')
                    if not line or line.startswith('#'):
                        continue
                    parts = line.split('\t')
                    if len(parts) >= 5:
                        try: mt = int(parts[2])
                        except Exception: mt = 0
                        self.entries[parts[3]] = {'mtime': mt, 'hash': parts[4]}
        except FileNotFoundError:
            pass
    def update(self, edge, state):
        cmd = edge_command(edge, state)
        h = command_hash(cmd)
        mtimes = []
        for n in edge.outputs:
            try: mtimes.append(os.stat(n.path).st_mtime_ns)
            except FileNotFoundError: pass
        mt = max(mtimes) if mtimes else int(time.time() * 1e9)
        for n in edge.outputs:
            self.entries[n.path] = {'mtime': mt, 'hash': h}
    def write(self):
        d = os.path.dirname(self.path)
        if d:
            os.makedirs(d, exist_ok=True)
        with open(self.path, 'w', encoding='utf-8') as f:
            f.write('# ninja log v7\n')
            for out, e in self.entries.items():
                f.write(f"0\t0\t{int(e.get('mtime',0))}\t{out}\t{e.get('hash','')}\n")

class DepsLog:
    def __init__(self, path):
        self.path = path
        self.deps = {}  # output -> {'mtime': int, 'deps':[paths]}
    def load(self):
        self.deps = {}
        try:
            with open(self.path, 'r', encoding='utf-8', errors='surrogateescape') as f:
                data = json.load(f)
            if isinstance(data, dict):
                self.deps = data
        except Exception:
            self.deps = {}
    def write(self):
        if not self.deps:
            return
        d = os.path.dirname(self.path)
        if d:
            os.makedirs(d, exist_ok=True)
        with open(self.path, 'w', encoding='utf-8') as f:
            json.dump(self.deps, f, separators=(',', ':'))
    def update(self, output, deps, mtime):
        self.deps[output] = {'mtime': int(mtime), 'deps': deps}

class BuildContext:
    def __init__(self, state, opts):
        self.state = state
        self.opts = opts
        builddir = state.root_scope.lookup_var('builddir')
        if builddir:
            os.makedirs(builddir, exist_ok=True)
        self.log = BuildLog(os.path.join(builddir, '.ninja_log') if builddir else '.ninja_log')
        self.depslog = DepsLog(os.path.join(builddir, '.ninja_deps') if builddir else '.ninja_deps')
        self.log.load(); self.depslog.load()
        self.explained = set()
        self.ran_edges = set()
        self.restat_clean = set()
    def explain(self, msg):
        if 'explain' in self.opts.debug:
            print(f"ninja explain: {msg}", file=sys.stderr)

# Depfile parsing: enough for GCC style "out: a b\\ c".
def parse_depfile(path):
    try:
        data = open(path, 'r', encoding='utf-8', errors='surrogateescape').read()
    except FileNotFoundError:
        return None
    # Join escaped newlines.
    data = data.replace('\\\n', ' ')
    colon = data.find(':')
    if colon >= 0:
        data = data[colon+1:]
    deps = []
    cur = []
    i = 0
    while i < len(data):
        c = data[i]
        if c in ' \t\r\n':
            if cur:
                deps.append(''.join(cur)); cur=[]
            i += 1
            continue
        if c == '\\' and i+1 < len(data):
            nxt = data[i+1]
            if nxt in ' \t#:\\':
                cur.append(nxt); i += 2; continue
            # Preserve unknown escapes as the following char, close enough.
            cur.append(nxt); i += 2; continue
        cur.append(c); i += 1
    if cur: deps.append(''.join(cur))
    return deps

# ---------- graph selection / dirty checking ----------

def suggest(name, choices):
    m = difflib.get_close_matches(name, choices, n=1, cutoff=0.6)
    return m[0] if m else None

def resolve_target(state, name):
    special = False
    if name.endswith('^'):
        special = True
        name = name[:-1]
    cname = state.canonical(name)
    node = state.nodes.get(cname)
    if node is None:
        s = suggest(cname, list(state.nodes.keys()))
        if s:
            raise BuildError(f"ninja: error: unknown target '{cname}', did you mean '{s}'?")
        raise BuildError(f"ninja: error: unknown target '{cname}'")
    if special:
        if not node.out_edges:
            raise BuildError(f"ninja: error: '{cname}' has no out edge")
        e = sorted(node.out_edges, key=lambda x: x.index)[0]
        return e.explicit_outputs[0] if e.explicit_outputs else e.outputs[0]
    return node

def root_targets(state):
    roots = []
    for n in state.nodes.values():
        if n.in_edge is not None and not n.out_edges:
            roots.append(n)
    # Unique edges/nodes in creation order.
    return roots

def target_nodes_for_args(state, args):
    if args:
        return [resolve_target(state, a) for a in args]
    if state.defaults:
        return list(state.defaults)
    roots = root_targets(state)
    if not roots and state.edges:
        raise BuildError("ninja: error: could not determine root nodes of build graph")
    return roots

def detect_cycle_from(node, visiting, visited, stack):
    if node in visiting:
        idx = stack.index(node) if node in stack else 0
        cyc = stack[idx:] + [node]
        raise BuildError("ninja: error: dependency cycle: " + " -> ".join(n.path for n in cyc))
    if node in visited:
        return
    visiting.add(node); stack.append(node)
    e = node.in_edge
    if e:
        for inp in e.explicit_inputs + e.implicit_inputs + e.order_only_inputs:
            detect_cycle_from(inp, visiting, visited, stack)
    visiting.remove(node); visited.add(node); stack.pop()

def ensure_inputs_known(edge):
    for n in edge.explicit_inputs + edge.implicit_inputs + edge.order_only_inputs:
        if n.in_edge is None and not os.path.exists(n.path):
            out = edge.explicit_outputs[0].path if edge.explicit_outputs else (edge.outputs[0].path if edge.outputs else '')
            raise BuildError(f"ninja: error: '{n.path}', needed by '{out}', missing and no known rule to make it")

def output_mtime(edge):
    mtimes = []
    missing = []
    for n in edge.outputs:
        try:
            mtimes.append(os.stat(n.path).st_mtime_ns)
        except FileNotFoundError:
            missing.append(n.path)
    if missing:
        return None, missing
    return (min(mtimes) if mtimes else 0), []

def all_input_mtimes(edge, ctx, include_order=False):
    items = edge.explicit_inputs + edge.implicit_inputs
    if include_order:
        items += edge.order_only_inputs
    out = []
    for n in items:
        try:
            out.append((n.path, os.stat(n.path).st_mtime_ns))
        except FileNotFoundError:
            pass
    # depfile/deps-log discovered deps are treated as implicit for dirtiness.
    for dep in discovered_deps(edge, ctx):
        try:
            out.append((dep, os.stat(dep).st_mtime_ns))
        except FileNotFoundError:
            out.append((dep, None))
    return out

def discovered_deps(edge, ctx):
    depfile = eval_edge_var(edge, 'depfile', ctx.state)
    depsmode = eval_edge_var(edge, 'deps', ctx.state)
    outs = [n.path for n in edge.explicit_outputs] or [n.path for n in edge.outputs]
    if depsmode == 'gcc':
        result = []
        for o in outs:
            ent = ctx.depslog.deps.get(o)
            if ent:
                result += ent.get('deps', [])
        return result
    if depfile:
        deps = parse_depfile(depfile)
        return deps or []
    return []

def edge_dirty_initial(edge, ctx, memo, stack=None):
    if edge in memo:
        return memo[edge]
    if stack is None: stack=set()
    if edge in stack:
        return False
    stack.add(edge)
    if edge.is_phony():
        dirty = False
        for n in edge.explicit_inputs + edge.implicit_inputs:
            if n.in_edge and edge_dirty_initial(n.in_edge, ctx, memo, stack):
                dirty = True
        memo[edge] = dirty; stack.remove(edge); return dirty
    ensure_inputs_known(edge)
    mt, missing = output_mtime(edge)
    if missing:
        ctx.explain(f"output {missing[0]} doesn't exist")
        memo[edge] = True; stack.remove(edge); return True
    # Dependencies' own dirtiness propagates through normal inputs only.
    for n in edge.normal_inputs:
        if n.in_edge and edge_dirty_initial(n.in_edge, ctx, memo, stack):
            ctx.explain(f"{n.path} is dirty")
            memo[edge] = True; stack.remove(edge); return True
    # Order-only deps must be buildable, but don't dirty this edge.
    for n in edge.order_only_inputs:
        if n.in_edge:
            edge_dirty_initial(n.in_edge, ctx, memo, stack)
    # Depfile/deps availability.
    depfile = eval_edge_var(edge, 'depfile', ctx.state)
    depsmode = eval_edge_var(edge, 'deps', ctx.state)
    if depsmode == 'gcc':
        out0 = edge.explicit_outputs[0].path if edge.explicit_outputs else edge.outputs[0].path
        if out0 not in ctx.depslog.deps:
            ctx.explain(f"deps for '{out0}' are missing")
            memo[edge] = True; stack.remove(edge); return True
    elif depfile:
        if not os.path.exists(depfile):
            ctx.explain(f"depfile '{depfile}' is missing")
            memo[edge] = True; stack.remove(edge); return True
    # Input mtimes.
    most = None
    for p, imt in all_input_mtimes(edge, ctx):
        if imt is None:
            ctx.explain(f"{p} is dirty")
            memo[edge] = True; stack.remove(edge); return True
        if most is None or imt > most[1]:
            most = (p, imt)
    if most and mt is not None and mt < most[1]:
        ctx.explain(f"output {edge.outputs[0].path} older than most recent input {most[0]} ({mt} vs {most[1]})")
        memo[edge] = True; stack.remove(edge); return True
    # Command hash log, skipped for generator rules.
    if not truthy(eval_edge_var(edge, 'generator', ctx.state)):
        cmdh = command_hash(edge_command(edge, ctx.state))
        out0 = edge.explicit_outputs[0].path if edge.explicit_outputs else edge.outputs[0].path
        ent = ctx.log.entries.get(out0)
        if ent is None:
            ctx.explain(f"command line not found in log for {out0}")
            memo[edge] = True; stack.remove(edge); return True
        if ent.get('hash') != cmdh:
            ctx.explain(f"command line changed for {out0}")
            memo[edge] = True; stack.remove(edge); return True
    memo[edge] = False; stack.remove(edge); return False

def edge_dirty_now(edge, ctx):
    if edge.is_phony():
        return False
    mt, missing = output_mtime(edge)
    if missing:
        return True
    # If a normal input edge ran and wasn't restat-clean, this edge remains dirty.
    for n in edge.normal_inputs:
        if n.in_edge in ctx.ran_edges and n.in_edge not in ctx.restat_clean:
            return True
    # Dep availability.
    depfile = eval_edge_var(edge, 'depfile', ctx.state)
    depsmode = eval_edge_var(edge, 'deps', ctx.state)
    if depsmode == 'gcc':
        out0 = edge.explicit_outputs[0].path if edge.explicit_outputs else edge.outputs[0].path
        if out0 not in ctx.depslog.deps:
            return True
    elif depfile and not os.path.exists(depfile):
        return True
    most = None
    for p, imt in all_input_mtimes(edge, ctx):
        if imt is None:
            return True
        if most is None or imt > most[1]:
            most = (p, imt)
    if most and mt is not None and mt < most[1]:
        return True
    if not truthy(eval_edge_var(edge, 'generator', ctx.state)):
        cmdh = command_hash(edge_command(edge, ctx.state))
        out0 = edge.explicit_outputs[0].path if edge.explicit_outputs else edge.outputs[0].path
        ent = ctx.log.entries.get(out0)
        if ent is None or ent.get('hash') != cmdh:
            return True
    return False

def collect_reachable_edges_from_node(node, acc, include_validations=True):
    e = node.in_edge
    if not e or e in acc:
        return
    for n in e.explicit_inputs + e.implicit_inputs + e.order_only_inputs:
        collect_reachable_edges_from_node(n, acc, include_validations)
    if include_validations:
        for n in e.validations:
            collect_reachable_edges_from_node(n, acc, include_validations)
    acc.add(e)

def collect_all_reachable(targets, include_validations=True):
    acc = set()
    for t in targets:
        collect_reachable_edges_from_node(t, acc, include_validations)
    return acc

def make_plan_batches(edges):
    remaining = set(edges)
    done = set()
    batches = []
    while remaining:
        ready = []
        for e in list(remaining):
            deps = set()
            for n in e.explicit_inputs + e.implicit_inputs + e.order_only_inputs + e.validations:
                if n.in_edge in remaining or n.in_edge in edges:
                    if n.in_edge in edges:
                        deps.add(n.in_edge)
            if deps.issubset(done):
                ready.append(e)
        if not ready:
            # Cycle among selected edges; fall back to declaration order to avoid hang.
            ready = list(remaining)
        ready.sort(key=lambda x: x.index)
        batches.append(ready)
        for e in ready:
            remaining.remove(e); done.add(e)
    return batches

# ---------- build execution ----------

def validate_status_format(fmt):
    allowed = set('stprufoc eEwWP%'.replace(' ', ''))
    i = 0
    while i < len(fmt):
        if fmt[i] == '%':
            if i+1 >= len(fmt) or fmt[i+1] not in allowed:
                bad = fmt[i+1] if i+1 < len(fmt) else ''
                raise FatalError(f"ninja: fatal: unknown placeholder '%{bad}' in $NINJA_STATUS")
            i += 2
        else:
            i += 1

def format_status(fmt, started, total, finished, running, remaining, start_time):
    elapsed = max(0.0, time.time() - start_time)
    pct = int((finished * 100) / total) if total else 100
    def hms(sec):
        sec = int(sec)
        m, s = divmod(sec, 60); h, m = divmod(m, 60)
        return f"{h}:{m:02d}:{s:02d}" if h else f"{m:02d}:{s:02d}"
    repl = {
        's': str(started), 't': str(total), 'p': f"{pct:3d}%", 'r': str(running),
        'u': str(remaining), 'f': str(finished), 'o': '0.0', 'c': '0.0',
        'e': f"{elapsed:.3f}", 'E': '0.000', 'w': hms(elapsed), 'W': '00:00',
        'P': f"{pct:3d}%", '%': '%'
    }
    out=[]; i=0
    while i < len(fmt):
        if fmt[i]=='%' and i+1 < len(fmt):
            out.append(repl.get(fmt[i+1], '')); i += 2
        else:
            out.append(fmt[i]); i += 1
    return ''.join(out)

def run_build(state, opts, targets):
    for w in state.warnings:
        print(w, file=sys.stderr)
    # Cycle detection.
    visited=set(); visiting=set()
    for t in targets:
        detect_cycle_from(t, visiting, visited, [])
    ctx = BuildContext(state, opts)
    reachable = collect_all_reachable(targets, include_validations=True)
    memo = {}
    dirty = set()
    # Evaluate dirty for all reachable in declaration order so explanations are stable.
    for e in sorted(reachable, key=lambda x: x.index):
        if not e.is_phony() and edge_dirty_initial(e, ctx, memo):
            dirty.add(e)
    if not dirty:
        if not opts.quiet:
            print("ninja: no work to do.")
        return 0
    batches = make_plan_batches(dirty)
    total = len(dirty)
    status_fmt = os.environ.get('NINJA_STATUS', '[%f/%t] ')
    validate_status_format(status_fmt)
    start_time = time.time()
    printed = 0
    failures = 0
    stop = False
    # Dry-run pretends every dirty edge ran successfully; no restat/log updates.
    for batch in batches:
        batch_fail_before = failures
        for edge in batch:
            if not opts.dry_run and not edge_dirty_now(edge, ctx):
                continue
            printed += 1
            cmd = edge_command(edge, state)
            desc = edge_description(edge, state)
            to_show = cmd if opts.verbose or not desc else desc
            pool = eval_edge_var(edge, 'pool', state)
            if not opts.quiet:
                prefix = '' if status_fmt == '' else format_status(status_fmt, min(total, printed), total, printed, max(1, len(batch)), max(0, total-printed), start_time)
                print(prefix + to_show)
            if opts.dry_run:
                ctx.ran_edges.add(edge)
                continue
            # Response file.
            rsp = eval_edge_var(edge, 'rspfile', state)
            if rsp:
                content = eval_edge_var(edge, 'rspfile_content', state)
                d = os.path.dirname(rsp)
                if d: os.makedirs(d, exist_ok=True)
                with open(rsp, 'w', encoding='utf-8', errors='surrogateescape') as f:
                    f.write(content)
            before_mtimes = {}
            for n in edge.outputs:
                try: before_mtimes[n.path] = os.stat(n.path).st_mtime_ns
                except FileNotFoundError: before_mtimes[n.path] = None
            if pool == 'console':
                res = subprocess.run(cmd, shell=True)
                output = b''
            else:
                res = subprocess.run(cmd, shell=True, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
                output = res.stdout or b''
            if res.returncode != 0:
                failures += 1
                outs = ' '.join(n.path for n in edge.explicit_outputs)
                print(f"FAILED: [code={res.returncode}] {outs} ")
                print(cmd)
                if output:
                    sys.stdout.buffer.write(output)
                    if not output.endswith(b'\n'):
                        sys.stdout.write('\n')
                continue
            if output:
                sys.stdout.buffer.write(output)
                if not output.endswith(b'\n'):
                    sys.stdout.write('\n')
            ctx.ran_edges.add(edge)
            # Restat detection.
            if truthy(eval_edge_var(edge, 'restat', state)):
                unchanged = True
                for n in edge.outputs:
                    try: after = os.stat(n.path).st_mtime_ns
                    except FileNotFoundError: after = None
                    if after != before_mtimes.get(n.path):
                        unchanged = False
                if unchanged:
                    ctx.restat_clean.add(edge)
            # Metadata.
            ctx.log.update(edge, state)
            depfile = eval_edge_var(edge, 'depfile', state)
            depsmode = eval_edge_var(edge, 'deps', state)
            if depfile:
                deps = parse_depfile(depfile) or []
                if depsmode == 'gcc':
                    mt = int(time.time()*1e9)
                    for n in edge.explicit_outputs or edge.outputs:
                        try: mt = os.stat(n.path).st_mtime_ns
                        except FileNotFoundError: pass
                        ctx.depslog.update(n.path, deps, mt)
                    if 'keepdepfile' not in opts.debug:
                        try: os.remove(depfile)
                        except FileNotFoundError: pass
            if rsp and 'keeprsp' not in opts.debug:
                try: os.remove(rsp)
                except FileNotFoundError: pass
            ctx.log.write(); ctx.depslog.write()
        if failures != batch_fail_before and opts.keep_going != 0 and failures >= opts.keep_going:
            stop = True
            break
    if failures:
        if opts.keep_going == 0:
            print("ninja: build stopped: cannot make progress due to previous errors.")
        elif failures == 1:
            print("ninja: build stopped: subcommand failed.")
        else:
            print("ninja: build stopped: subcommands failed.")
        return 1
    return 0

# ---------- subtools ----------

def print_tool_list():
    print("ninja subtools:")
    for name, desc in TOOLS:
        print(f"{name:>11}  {desc}")

def tool_rules(state, args):
    detailed = False
    if args and args[0] == '-d':
        detailed = True
    names = set(state.root_scope.rules.keys()) | {'phony'}
    for name in sorted(names):
        if detailed and name != 'phony':
            rule = state.root_scope.rules.get(name)
            desc = rule.bindings.get('description') if rule else None
            if desc:
                # Pretty-print variable refs in the same style as Ninja's EvalString dump.
                desc2 = re.sub(r'\$([A-Za-z0-9_.-]+)', r'${\1}', desc)
                print(f"{name}: {desc2}")
            else:
                print(name)
        else:
            print(name)
    return 0

def edge_label(edge):
    return edge.rule_name

def tool_targets(state, args):
    mode = 'depth'; rest=[]
    if args:
        if args[0] in ('rule','depth','all'):
            mode=args[0]; rest=args[1:]
        else:
            s = 'all'
            raise BuildError(f"ninja: error: unknown target tool mode '{args[0]}', did you mean '{s}'?")
    if mode == 'all':
        for e in state.edges:
            for n in e.outputs:
                print(f"{n.path}: {edge_label(e)}")
        return 0
    if mode == 'rule':
        if rest:
            rn = rest[0]
            outs=[]
            for e in state.edges:
                if e.rule_name == rn:
                    outs += [n.path for n in e.explicit_outputs]
            for p in sorted(outs):
                print(p)
        else:
            # Source leaves in node creation order.
            for n in state.nodes.values():
                if n.in_edge is None and n.out_edges:
                    print(n.path)
        return 0
    # depth mode
    depth = 1
    if rest:
        try: depth = int(rest[0])
        except Exception: depth = 1
    roots = root_targets(state)
    if not roots and state.edges:
        raise BuildError("ninja: error: could not determine root nodes of build graph")
    seen_edges=set()
    def rec(n, d):
        indent = '  '*d
        if n.in_edge:
            print(f"{indent}{n.path}: {edge_label(n.in_edge)}")
            if depth == 0 or d+1 < depth:
                for inp in n.in_edge.explicit_inputs + n.in_edge.implicit_inputs:
                    rec(inp, d+1)
        else:
            print(f"{indent}{n.path}")
    for r in roots:
        rec(r, 0)
    return 0

def tool_query(state, args):
    if not args:
        return 0
    for a in args:
        n = resolve_target(state, a)
        print(f"{n.path}:")
        if n.in_edge:
            e = n.in_edge
            print(f"  input: {edge_label(e)}")
            for inp in e.explicit_inputs:
                print(f"    {inp.path}")
            for inp in e.implicit_inputs:
                print(f"    | {inp.path}")
            for inp in e.order_only_inputs:
                print(f"    || {inp.path}")
            if e.validations:
                print("  validations:")
                for v in e.validations:
                    print(f"    {v.path}")
        print("  outputs:")
        for oe in sorted(n.out_edges, key=lambda x:x.index):
            for out in oe.outputs:
                print(f"    {out.path}")
    return 0

def command_edges_for_targets(state, target_args, include_validations=False, final_only=False):
    targets = target_nodes_for_args(state, target_args)
    if final_only:
        es=[]
        for t in targets:
            if t.in_edge and not t.in_edge.is_phony() and t.in_edge not in es:
                es.append(t.in_edge)
        return es
    acc = collect_all_reachable(targets, include_validations=include_validations)
    es = [e for e in acc if not e.is_phony()]
    return [e for batch in make_plan_batches(set(es)) for e in batch]

def tool_commands(state, args):
    final_only = False
    if args and args[0] == '-s':
        final_only=True; args=args[1:]
    for e in command_edges_for_targets(state, args, include_validations=False, final_only=final_only):
        print(edge_command(e, state))
    return 0

def collect_inputs_for_node(node, include_order=True, seen_edges=None, out=None):
    if seen_edges is None: seen_edges=set()
    if out is None: out=[]
    e = node.in_edge
    if not e:
        return out
    if e in seen_edges:
        return out
    seen_edges.add(e)
    for inp in e.explicit_inputs + e.implicit_inputs + (e.order_only_inputs if include_order else []):
        if inp.in_edge:
            collect_inputs_for_node(inp, include_order, seen_edges, out)
        out.append(inp.path)
    return out

def inputs_usage():
    return """Usage '-t inputs [options] [targets]

List all inputs used for a set of targets, sorted in dependency order.
Note that by default, results are shell escaped, and sorted alphabetically,
and never include validation target paths.

Options:
  -h, --help          Print this message.
  -0, --print0            Use \\0, instead of \\n as a line terminator.
  -E, --no-shell-escape   Do not shell escape the result.
  -d, --dependency-order  Sort results by dependency order."""

def tool_inputs(state, args):
    print0=False; noesc=False; deporder=False
    rest=[]
    for a in args:
        if a in ('-h','--help'):
            print(inputs_usage()); return 1
        elif a in ('-0','--print0'):
            print0=True
        elif a in ('-E','--no-shell-escape'):
            noesc=True
        elif a in ('-d','--dependency-order'):
            deporder=True
        else:
            rest.append(a)
    targets = target_nodes_for_args(state, rest)
    vals=[]
    for t in targets:
        vals += collect_inputs_for_node(t)
    if deporder:
        seen=set(); ordered=[]
        for v in vals:
            if v not in seen:
                seen.add(v); ordered.append(v)
        vals = ordered
    else:
        if noesc:
            vals = sorted(set(vals))
        else:
            vals = sorted(set(shlex.quote(v) for v in vals))
            term = '\0' if print0 else '\n'
            sys.stdout.write(term.join(vals) + (term if vals else ''))
            return 0
    if not noesc:
        vals = [shlex.quote(v) for v in vals]
    term = '\0' if print0 else '\n'
    sys.stdout.write(term.join(vals) + (term if vals else ''))
    return 0

def multi_inputs_usage():
    return """Usage '-t multi-inputs [options] [targets]

Print one or more sets of inputs required to build targets, sorted in dependency order.
The tool works like inputs tool but with addition of the target for each line.
The output will be a series of lines with the following elements:
<target> <delimiter> <input> <terminator>
Note that a given input may appear for several targets if it is used by more than one targets.
Options:
  -h, --help                   Print this message.
  -d  --delimiter=DELIM        Use DELIM instead of TAB for field delimiter.
  -0, --print0                 Use \\0, instead of \\n as a line terminator."""

def tool_multi_inputs(state, args):
    delim='\t'; print0=False; rest=[]; i=0
    while i < len(args):
        a=args[i]
        if a in ('-h','--help'):
            print(multi_inputs_usage()); return 1
        elif a in ('-0','--print0'):
            print0=True
        elif a.startswith('--delimiter='):
            delim=a.split('=',1)[1]
        elif a == '--delimiter' or a == '-d':
            if i+1 < len(args): delim=args[i+1]; i+=1
        else:
            rest.append(a)
        i+=1
    targets = target_nodes_for_args(state, rest)
    term='\0' if print0 else '\n'
    chunks=[]
    for t in targets:
        seen=set()
        for v in collect_inputs_for_node(t):
            if v in seen: continue
            seen.add(v)
            chunks.append(f"{t.path}{delim}{v}")
    sys.stdout.write(term.join(chunks) + (term if chunks else ''))
    return 0

def clean_usage():
    return """usage: ninja -t clean [options] [targets]

options:
  -g     also clean files marked as ninja generator output
  -r     interpret targets as a list of rules to clean instead"""

def clean_edges_for_targets(state, args):
    targets = target_nodes_for_args(state, args) if args else [n for e in state.edges for n in e.outputs]
    acc=set()
    for t in targets:
        collect_reachable_edges_from_node(t, acc, include_validations=False)
    return acc

def tool_clean(state, opts, args):
    include_gen=False; by_rule=False; rest=[]
    for a in args:
        if a == '-h':
            print(clean_usage()); return 1
        elif a == '-g': include_gen=True
        elif a == '-r': by_rule=True
        else: rest.append(a)
    if by_rule:
        edges = [e for e in state.edges if e.rule_name in rest]
    elif rest:
        edges = list(clean_edges_for_targets(state, rest))
    else:
        edges = list(state.edges)
    files=[]
    for e in sorted(edges, key=lambda x:x.index):
        if e.is_phony(): continue
        if truthy(eval_edge_var(e, 'generator', state)) and not include_gen: continue
        for n in e.outputs:
            if n.path not in files:
                files.append(n.path)
    existing = [p for p in files if os.path.exists(p)]
    verbose = opts.verbose or opts.dry_run
    if verbose:
        print("Cleaning...")
        for p in existing:
            print(f"Remove {p}")
    if not opts.dry_run:
        for p in existing:
            try: os.remove(p)
            except FileNotFoundError: pass
            except IsADirectoryError: pass
    if verbose:
        print(f"{len(existing)} files.")
    else:
        print(f"Cleaning... {len(existing)} files.")
    return 0

def tool_cleandead(state, opts):
    ctx = BuildContext(state, opts)
    current = {n.path for e in state.edges for n in e.outputs}
    dead = [p for p in ctx.log.entries.keys() if p not in current and os.path.exists(p)]
    verbose = opts.verbose or opts.dry_run
    if verbose:
        print("Cleaning...")
        for p in dead: print(f"Remove {p}")
    if not opts.dry_run:
        for p in dead:
            try: os.remove(p)
            except OSError: pass
            ctx.log.entries.pop(p, None)
        ctx.log.write()
    if verbose:
        print(f"{len(dead)} files.")
    else:
        print(f"Cleaning... {len(dead)} files.")
    return 0

def tool_deps(state, opts, args):
    ctx = BuildContext(state, opts)
    filt = set()
    for a in args:
        filt.add(resolve_target(state, a).path)
    for out in sorted(ctx.depslog.deps.keys()):
        if filt and out not in filt: continue
        ent = ctx.depslog.deps[out]
        deps = ent.get('deps', [])
        mt = ent.get('mtime', 0)
        print(f"{out}: #deps {len(deps)}, deps mtime {mt} (VALID)")
        for d in deps:
            print(f"    {d}")
    return 0

def tool_restat(state, opts):
    ctx = BuildContext(state, opts)
    for p, ent in list(ctx.log.entries.items()):
        try: ent['mtime'] = os.stat(p).st_mtime_ns
        except FileNotFoundError: pass
    ctx.log.write()
    return 0

def tool_compdb_common(state, edges, expand_rsp):
    entries=[]
    cwd=os.getcwd()
    for e in edges:
        if e.is_phony(): continue
        cmd=edge_command(e, state)
        if expand_rsp:
            rsp=eval_edge_var(e, 'rspfile', state)
            if rsp:
                cmd=cmd.replace('@'+rsp, eval_edge_var(e, 'rspfile_content', state))
        out=' '.join(n.path for n in e.explicit_outputs)
        for inp in e.explicit_inputs:
            entries.append(OrderedDict([('directory', cwd), ('command', cmd), ('file', inp.path), ('output', out)]))
    print(json.dumps(entries, indent=2))
    return 0

def compdb_usage():
    return """usage: ninja -t compdb [options] [rules]

options:
  -x     expand @rspfile style response file invocations"""

def tool_compdb(state, args):
    expand=False; rules=[]
    for a in args:
        if a == '-h': print(compdb_usage()); return 1
        elif a == '-x': expand=True
        else: rules.append(a)
    selected=[]
    for e in state.edges:
        if e.is_phony(): continue
        if not rules or e.rule_name in rules:
            selected.append(e)
    return tool_compdb_common(state, selected, expand)

def compdb_targets_usage():
    return """usage: ninja -t compdb [-hx] target [targets]

options:
  -h     display this help message
  -x     expand @rspfile style response file invocations"""

def tool_compdb_targets(state, args):
    expand=False; rest=[]
    for a in args:
        if a == '-h': print(compdb_targets_usage()); return 1
        elif a == '-x': expand=True
        else: rest.append(a)
    if not rest:
        print(compdb_targets_usage())
        print("ninja: error: compdb-targets expects the name of at least one target", file=sys.stderr)
        return 1
    edges=command_edges_for_targets(state, rest, include_validations=False)
    return tool_compdb_common(state, edges, expand)

def tool_graph(state, args):
    targets = target_nodes_for_args(state, args)
    ids={}; counter=[0]
    def gid(obj):
        if obj not in ids:
            ids[obj]=f"0x{counter[0]:x}"; counter[0]+=1
        return ids[obj]
    printed_nodes=set(); printed_edges=set()
    print('digraph ninja {')
    print('rankdir="LR"')
    print('node [fontsize=10, shape=box, height=0.25]')
    print('edge [fontsize=10]')
    def esc(s): return s.replace('\\','\\\\').replace('"','\\"')
    def rec_node(n):
        if n not in printed_nodes:
            print(f'"{gid(n)}" [label="{esc(n.path)}"]')
            printed_nodes.add(n)
        if n.in_edge:
            rec_edge(n.in_edge)
    def rec_edge(e):
        if e in printed_edges: return
        printed_edges.add(e)
        if not e.is_phony():
            print(f'"{gid(e)}" [label="{esc(e.rule_name)}", shape=ellipse]')
        for out in e.outputs:
            if out not in printed_nodes:
                print(f'"{gid(out)}" [label="{esc(out.path)}"]')
                printed_nodes.add(out)
            if not e.is_phony(): print(f'"{gid(e)}" -> "{gid(out)}"')
        for inp in e.explicit_inputs + e.implicit_inputs:
            rec_node(inp)
            if not e.is_phony(): print(f'"{gid(inp)}" -> "{gid(e)}" [arrowhead=none]')
        for inp in e.order_only_inputs:
            rec_node(inp)
            if not e.is_phony(): print(f'"{gid(inp)}" -> "{gid(e)}" [arrowhead=none style=dotted]')
    for t in targets: rec_node(t)
    print('}')
    return 0

def tool_missingdeps(state, args):
    # Full missing-deps analysis requires compiler deps logs. For clean graphs,
    # Ninja reports this concise success message.
    targets = target_nodes_for_args(state, args)
    edges = collect_all_reachable(targets, include_validations=False)
    nodes = set(targets)
    for e in edges:
        for n in e.outputs + e.inputs:
            nodes.add(n)
    print(f"Processed {len(nodes)} nodes.")
    print("No missing dependencies on generated files found.")
    return 0

def run_tool(state, opts):
    tool=opts.tool; args=opts.tool_args
    if tool == 'list': print_tool_list(); return 0
    if tool == 'rules': return tool_rules(state, args)
    if tool == 'targets': return tool_targets(state, args)
    if tool == 'query': return tool_query(state, args)
    if tool == 'commands': return tool_commands(state, args)
    if tool == 'inputs': return tool_inputs(state, args)
    if tool == 'multi-inputs': return tool_multi_inputs(state, args)
    if tool == 'clean': return tool_clean(state, opts, args)
    if tool == 'cleandead': return tool_cleandead(state, opts)
    if tool == 'deps': return tool_deps(state, opts, args)
    if tool == 'recompact': return 0
    if tool == 'restat': return tool_restat(state, opts)
    if tool == 'compdb': return tool_compdb(state, args)
    if tool == 'compdb-targets': return tool_compdb_targets(state, args)
    if tool == 'graph': return tool_graph(state, args)
    if tool == 'missingdeps': return tool_missingdeps(state, args)
    if tool == 'browse':
        print("ninja: python is required for the browse tool")
        return 1
    raise FatalError(f"ninja: fatal: unknown tool '{tool}'")

# ---------- CLI ----------

def parse_int_param(opt, val):
    try:
        if val.startswith('+'): val = val[1:]
        if not re.match(r'^-?[0-9]+$', val): raise ValueError
        return int(val)
    except Exception:
        raise FatalError(f"ninja: fatal: invalid {opt} parameter")

def parse_float_param(opt, val):
    try: return float(val)
    except Exception: raise FatalError(f"ninja: fatal: invalid {opt} parameter")

def option_error(prog, msg):
    print(f"{prog}: {msg}", file=sys.stderr)
    print(usage_text(), file=sys.stderr)
    return 1

def parse_args(argv):
    opts=Options(); prog=argv[0]; i=1
    while i < len(argv):
        a=argv[i]
        if a == '--':
            opts.targets += argv[i+1:]; break
        if a == '--version':
            print(VERSION); sys.exit(0)
        if a in ('-h','--help'):
            print(usage_text(), file=sys.stderr); sys.exit(1)
        if a in ('-v','--verbose'):
            opts.verbose=True; i+=1; continue
        if a == '--quiet':
            opts.quiet=True; i+=1; continue
        if a == '-n':
            opts.dry_run=True; opts.verbose = opts.verbose; i+=1; continue
        def need_arg(ch):
            nonlocal i
            if i+1 >= len(argv):
                option_error(prog, f"option requires an argument -- '{ch}'"); sys.exit(1)
            i += 1; return argv[i]
        if a == '-C' or a.startswith('-C') and len(a)>2:
            val = a[2:] if len(a)>2 else need_arg('C')
            opts.chdir = val
            i += 1; continue
        if a == '-f' or a.startswith('-f') and len(a)>2:
            val = a[2:] if len(a)>2 else need_arg('f')
            opts.buildfile = val
            i += 1; continue
        if a == '-j' or a.startswith('-j') and len(a)>2:
            val = a[2:] if len(a)>2 else need_arg('j')
            opts.jobs = parse_int_param('-j', val)
            i += 1; continue
        if a == '-k' or a.startswith('-k') and len(a)>2:
            val = a[2:] if len(a)>2 else need_arg('k')
            opts.keep_going = parse_int_param('-k', val)
            i += 1; continue
        if a == '-l' or a.startswith('-l') and len(a)>2:
            val = a[2:] if len(a)>2 else need_arg('l')
            opts.load = parse_float_param('-l', val)
            i += 1; continue
        if a == '-d' or a.startswith('-d') and len(a)>2:
            val = a[2:] if len(a)>2 else need_arg('d')
            if val == 'list':
                print(DEBUG_LIST); sys.exit(1)
            if val not in ('stats','explain','keepdepfile','keeprsp'):
                raise FatalError(f"ninja: error: unknown debug setting '{val}'")
            opts.debug.add(val); i += 1; continue
        if a == '-w' or a.startswith('-w') and len(a)>2:
            val = a[2:] if len(a)>2 else need_arg('w')
            if val == 'list':
                print(WARN_LIST); sys.exit(1)
            if val == 'phonycycle=warn': opts.phonycycle='warn'
            elif val == 'phonycycle=err': opts.phonycycle='err'
            elif val.startswith('phonycycle='):
                raise FatalError(f"ninja: error: unknown warning flag '{val}', did you mean 'phonycycle=err'?")
            else:
                raise FatalError(f"ninja: error: unknown warning flag '{val}'")
            i += 1; continue
        if a == '-t' or a.startswith('-t') and len(a)>2:
            val = a[2:] if len(a)>2 else need_arg('t')
            opts.tool = val
            opts.tool_args = argv[i+1:]
            return opts
        if a.startswith('--'):
            option_error(prog, f"unrecognized option '{a}'"); sys.exit(1)
        if a.startswith('-') and a != '-':
            # Unknown short option; match getopt wording.
            option_error(prog, f"invalid option -- '{a[1]}'"); sys.exit(1)
        opts.targets.append(a); i += 1
    return opts

def maybe_rebuild_manifest(state, opts):
    # If the manifest is generated and dirty, rebuild it and reload once.
    bf = state.canonical(opts.buildfile)
    node = state.nodes.get(bf)
    if not node or not node.in_edge:
        return state
    ctx = BuildContext(state, opts)
    memo={}
    if node.in_edge.is_phony() or not edge_dirty_initial(node.in_edge, ctx, memo):
        return state
    # Build just the manifest edge with normal output, then reparse.
    old_targets = opts.targets[:]
    saved_tool = opts.tool
    opts.tool = None
    code = run_build(state, opts, [node])
    opts.tool = saved_tool
    if code != 0:
        sys.exit(code)
    new_state = State(opts)
    Parser(new_state).parse_file(opts.buildfile, new_state.root_scope)
    return new_state

def main(argv):
    try:
        opts = parse_args(argv)
        if opts.chdir:
            print(f"ninja: Entering directory `{opts.chdir}'")
            try:
                os.chdir(opts.chdir)
            except FileNotFoundError:
                print(f"ninja: fatal: chdir to '{opts.chdir}' - No such file or directory", file=sys.stderr)
                return 1
            except OSError as e:
                print(f"ninja: fatal: chdir to '{opts.chdir}' - {e.strerror}", file=sys.stderr)
                return 1
        if opts.tool == 'list':
            print_tool_list(); return 0
        state = State(opts)
        Parser(state).parse_file(opts.buildfile, state.root_scope)
        # Print parse warnings after successful parse, matching Ninja's behavior.
        if opts.tool:
            for w in state.warnings:
                print(w, file=sys.stderr)
            return run_tool(state, opts)
        state = maybe_rebuild_manifest(state, opts)
        targets = target_nodes_for_args(state, opts.targets)
        return run_build(state, opts, targets)
    except ParseError as e:
        print(e.format(), file=sys.stderr); return 1
    except FatalError as e:
        print(str(e), file=sys.stderr); return 1
    except BuildError as e:
        print(str(e), file=sys.stderr); return 1
    except BrokenPipeError:
        return 1

if __name__ == '__main__':
    sys.exit(main(sys.argv))
