#!/usr/bin/env python3
import sys, os, re, json, time, shlex, subprocess, hashlib, difflib
from collections import OrderedDict, defaultdict, deque

VERSION = "1.14.0.git"

RULE_VARS = {
    "command", "depfile", "deps", "msvc_deps_prefix", "description",
    "generator", "restat", "rspfile", "rspfile_content", "pool", "dyndep",
}

TOOLS = [
    ("browse", "browse dependency graph in a web browser"),
    ("clean", "clean built files"),
